import { ContentTypeResource } from "@/shared/types/content-type.types";
import type { CourseVisibility } from "@/shared/types/course.types";

export type Category = {
  id: string;
  name: string;
  parentId: string | null;
  description?: string;
  children?: Category[];
};

export type Course = {
  id: string;
  fullName: string;
  shortName: string;
  categoryId: string | null;
  /** Auto-generated by the backend (id_number). Read-only. */
  identifier: string | null;
  /** Derived: true when visibility === 'PUBLISHED'. */
  visible: boolean;
  visibility: CourseVisibility;
  description?: string;
};

export type ContentType = 'folder' | 'file' | 'page' | 'scorm' | 'survey' | 'url' | 'text-media';

export interface CourseContent {
  id: string;
  sectionId: string;
  type: string;
  title: string;
  data?: Record<string, unknown>;
  contentTypeResource?: ContentTypeResource;
}

export interface CourseSection {
  id: string;
  title: string;
  description?: string;
  order: number;
  contents: CourseContent[];
}

